// hid_delete_folder.ino — ESP32-S3 (native USB HID)
// GPIO4: Win+R -> cmd -> rd /s /q "%USERPROFILE%\Desktop\<папка>"
// Весь текст — через Alt+Numpad, раскладка не важна
#include "USB.h"
#include "USBHIDKeyboard.h"

USBHIDKeyboard Keyboard;

const int BTN = 0;
const char* FOLDER = "OldFolder";   // имя папки на рабочем столе, только латиница

const uint8_t KP_DIGITS[10] = {0x62, 0x59, 0x5A, 0x5B, 0x5C, 0x5D, 0x5E, 0x5F, 0x60, 0x61};
const uint8_t HID_ALT = 0xE2, HID_GUI = 0xE3, HID_R = 0x15, HID_ENTER = 0x28;
const uint8_t HID_NUMLOCK = 0x53;

struct Btn { uint8_t pin; bool lastReading = false, state = false; unsigned long lastChange = 0; };
Btn btn{BTN};

bool checkPress(Btn &b) {
  bool reading = (digitalRead(b.pin) == LOW);
  if (reading != b.lastReading) { b.lastChange = millis(); b.lastReading = reading; }
  if (millis() - b.lastChange > 20 && reading != b.state) {
    b.state = reading;
    if (b.state) return true;
  }
  return false;
}

void tapKey(uint8_t usage) {
  Keyboard.pressRaw(usage);
  Keyboard.releaseRaw(usage);
}

void typeAltChar(char c) {
  Keyboard.pressRaw(HID_ALT);
  tapKey(KP_DIGITS[0]);                       // 0 -> ANSI-таблица
  char digits[4];
  sprintf(digits, "%03d", (int)c);
  for (int i = 0; i < 3; i++) tapKey(KP_DIGITS[digits[i] - '0']);
  Keyboard.releaseRaw(HID_ALT);
}

void typeAltString(const char* s) {
  for (unsigned int i = 0; i < strlen(s); i++) typeAltChar(s[i]);
}

void runDelete() {
  tapKey(HID_NUMLOCK);

  Keyboard.pressRaw(HID_GUI);                 // Win+R
  Keyboard.pressRaw(HID_R);
  delay(20);
  Keyboard.releaseRaw(HID_R);
  Keyboard.releaseRaw(HID_GUI);
  delay(150);                                 // ждём окно Run

  // rd /s /q "...\Desktop\OldFolder" — удаление без корзины, без вопросов
  typeAltString("cmd /c rd /s /q \"%USERPROFILE%\\Desktop\\");
  typeAltString(FOLDER);
  typeAltChar('"');
  tapKey(HID_ENTER);
}

void setup() {
  pinMode(BTN, INPUT_PULLUP);
  Keyboard.begin();
  USB.begin();
}

void loop() {
  if (checkPress(btn)) runDelete();
}
